  if(count===1&&!isGroupedExamType(type)){const single=adaptGeometryPresentation(Object.assign(buildIn(u,type,difficulty,g,language),{partCount:1,visualMode:settings.visualByType?.[type]||(type==='geometrie'?'illustration':'text'),...(type==='vrai-faux'?tfSettings:{})}),settings.visualByType?.[type]||'illustration');if(type==='construction'){single.visual=null;single.visualMode='text';if(Number(settings.cycle)===3)single.text=(language==='en'?'On your separate answer sheet, ':'Sur ta feuille de réponses, ')+single.text;}return Number(settings.cycle)===3&&type==='geometrie'?prepareCycle3Geometry(single):single;}
